import { expect, test, type Page } from '@playwright/test';

/**
 * PROJECT-AREA-IA-001..005 in a real browser, against the real
 * published application with a real PostgreSQL behind it.
 *
 * This suite runs last in the first e2e group (see scripts/e2e.sh): it
 * creates its own project by name and never asserts global emptiness,
 * so the projects other suites in the group recorded do not disturb it.
 * Every capture is an empty/generic state, and no capture carries a
 * credential, a token, a PAT or a session value.
 *
 * The setup token is generated by scripts/e2e.sh for this run and handed to
 * the fixtures through the environment. It is never written into this file,
 * never printed and never asserted on.
 */
const ACCESS_TOKEN = process.env.CHRONICLEAF_E2E_ACCESS_TOKEN;

const PROJECT_NAME = 'Area map notes';

const AREAS = [
  { testid: 'project-area-overview', path: '' },
  { testid: 'project-area-evidence', path: '/evidence' },
  { testid: 'project-area-content', path: '/content' },
  { testid: 'project-area-publish', path: '/publish' },
  { testid: 'project-area-evolution', path: '/evolution' },
  { testid: 'project-area-automations', path: '/automations' },
] as const;

test.beforeEach(async ({ page }) => {
  if (!ACCESS_TOKEN) {
    throw new Error(
      'CHRONICLEAF_E2E_ACCESS_TOKEN is not set. Run these fixtures through scripts/e2e.sh, which ' +
        'starts the published application with a real access token hash and a real database.',
    );
  }

  await page.context().clearCookies();
  await page.goto('/');
  await signIn(page);
});

test('the sub-navigation reaches all six areas with the active one marked', async ({ page }) => {
  const projectId = await createProject(page, PROJECT_NAME, 'One project, six addresses.');

  for (const area of AREAS) {
    await page.getByTestId(area.testid).click();
    await expect(page).toHaveURL(new RegExp(`/projects/${projectId}${area.path}$`));
    await expect(page.getByTestId(area.testid)).toHaveAttribute('aria-current', 'page');
    await expect(page.getByTestId('project-subnav')).toBeVisible();
    await expect(page.getByTestId('project-name')).toHaveText(PROJECT_NAME);
  }

  // An unknown area is the delivered "Nothing here" view, with the sub-nav
  // intact so the owner is one click from a real area.
  await page.goto(`/projects/${projectId}/no-such-area`);
  await expect(page.getByRole('heading', { name: 'Nothing here', exact: true })).toBeVisible();
  await expect(page.getByTestId('project-subnav')).toBeVisible();
  await page.getByTestId('project-area-evidence').click();
  await expect(page).toHaveURL(new RegExp(`/projects/${projectId}/evidence$`));
});

test('each of the 20 panels renders on exactly one area', async ({ page }) => {
  await createProject(page, PROJECT_NAME, 'One project, six addresses.');
  await recordMilestone(page, 'Shipped the split');

  // Overview: the milestone list and the timeline excerpt, and nothing else.
  await expect(page.getByTestId('milestone-list')).toBeVisible();
  await expect(page.getByTestId('project-timeline')).toBeVisible();
  await expect(page.getByTestId('evidence-panel')).toHaveCount(0);
  await expect(page.getByTestId('draft-panel')).toHaveCount(0);
  await expect(page.getByTestId('publication-panel')).toHaveCount(0);
  await expect(page.getByTestId('capture-panel')).toHaveCount(0);

  // Evidence: connections, candidates, and the per-milestone evidence panels.
  await page.getByTestId('project-area-evidence').click();
  await expect(page.getByTestId('github-connection-panel')).toBeVisible();
  await expect(page.getByTestId('github-candidate-panel')).toBeVisible();
  await expect(page.getByTestId('evidence-panel')).toBeVisible();
  await expect(page.getByTestId('github-sync-panel')).toBeVisible();
  await expect(page.getByTestId('curation-panel')).toBeVisible();
  await expect(page.getByTestId('project-timeline')).toHaveCount(0);
  await expect(page.getByTestId('draft-panel')).toHaveCount(0);
  await expect(page.getByTestId('publication-panel')).toHaveCount(0);
  await expect(page.getByTestId('capture-panel')).toHaveCount(0);

  // Content: narrative, voice, and the per-milestone generation-to-review flow.
  await page.getByTestId('project-area-content').click();
  await expect(page.getByTestId('narrative-memory')).toBeVisible();
  // The voice panels are behind a toggle (the design's compact default); open it
  // to confirm the panel renders on this area with the same selectors the panel
  // suite asserts.
  await page.getByTestId('voice-toggle').click();
  await expect(page.getByTestId('voice-profile-panel')).toBeVisible();
  await expect(page.getByTestId('generation-panel')).toBeVisible();
  await expect(page.getByTestId('draft-panel')).toBeVisible();
  await expect(page.getByTestId('review-panel')).toBeVisible();
  await expect(page.getByTestId('variant-panel')).toBeVisible();
  await expect(page.getByTestId('evidence-panel')).toHaveCount(0);
  await expect(page.getByTestId('capture-panel')).toHaveCount(0);

  // Publish: the publication triggers and the journey projection, no milestone rows.
  await page.getByTestId('project-area-publish').click();
  await expect(page.getByTestId('publication-panel')).toBeVisible();
  await expect(page.getByTestId('journey-panel')).toBeVisible();
  await expect(page.getByTestId('milestone-list')).toHaveCount(0);
  await expect(page.getByTestId('evidence-panel')).toHaveCount(0);

  // Evolution: the rendered comparisons, the animations, and the captures behind them.
  await page.getByTestId('project-area-evolution').click();
  await expect(page.getByTestId('evolution-image-panel')).toBeVisible();
  await expect(page.getByTestId('evolution-gif-panel')).toBeVisible();
  await expect(page.getByTestId('capture-panel')).toBeVisible();
  await expect(page.getByTestId('curation-panel')).toHaveCount(0);
  await expect(page.getByTestId('draft-panel')).toHaveCount(0);

  // Automations: new components only — zero moved panels render here.
  await page.getByTestId('project-area-automations').click();
  await expect(page.getByTestId('automations-view')).toBeVisible();
  await expect(page.getByTestId('github-connection-panel')).toHaveCount(0);
  await expect(page.getByTestId('evidence-panel')).toHaveCount(0);
  await expect(page.getByTestId('publication-panel')).toHaveCount(0);
});

test('the Automations view reads every automatic subsystem over delivered routes', async ({
  page,
}) => {
  const projectId = await createProject(page, PROJECT_NAME, 'One project, six addresses.');

  await page.getByTestId('project-area-automations').click();
  await expect(page.getByTestId('automations-view')).toBeVisible();

  // No repository is connected, so the connection section is the honest
  // empty state — and it names the payoff, not just the form.
  await expect(page.getByTestId('automations-connection-empty')).toBeVisible();
  await expect(page.getByTestId('automations-connection-payoff')).toContainText('candidate sync');
  await expect(page.getByTestId('automations-connection-payoff')).toContainText('scheduled sync');

  // Candidate sync has never run here: the section says so rather than
  // showing a run it never read.
  await expect(page.getByTestId('automations-sync-empty')).toBeVisible();

  // The schedule read is the server's own 404, rendered as the unarmed
  // state with the arm form beside it.
  await expect(page.getByTestId('automations-schedule-empty')).toBeVisible();
  await expect(page.getByTestId('automations-schedule-form')).toBeVisible();

  // The webhook subscription read is the server's own null: not listening.
  await expect(page.getByTestId('automations-webhook-empty')).toBeVisible();

  // No background job has run for this project yet.
  await expect(page.getByTestId('automations-jobs-empty')).toBeVisible();

  // Publish history names the missing per-project route aloud and shows the
  // installation's recent publish jobs captioned as scope-wide.
  await expect(page.getByTestId('automations-publish-note')).toContainText(
    'no per-project publish-history route',
  );

  // The server agrees with the page on its own routes: the connection is
  // missing, the schedule is absent, and nothing is listening.
  const connection = await readRoute(page, `/api/projects/${projectId}/github-connection`);
  expect(connection.status).toBe(422);
  const schedule = await readRoute(page, `/api/projects/${projectId}/sync-schedule`);
  expect(schedule.status).toBe(404);
});

test('the Sync-now trigger reports the server answer instead of inventing one', async ({
  page,
}) => {
  await createProject(page, PROJECT_NAME, 'One project, six addresses.');
  await page.getByTestId('project-area-automations').click();

  // The server's own refusal for a sync with nothing connected is read
  // first from the route itself, then asserted on the page verbatim —
  // writing the expected code here instead would assert the panel says
  // what this file says.
  const direct = await page.evaluate(async () => {
    const metadata = await (
      await fetch('/api/session/antiforgery', { credentials: 'same-origin' })
    ).json();
    const projects = await (
      await fetch('/api/projects', { credentials: 'same-origin' })
    ).json();
    const id = projects.items[0].id as string;
    const record = await (await fetch(`/api/projects/${id}`, { credentials: 'same-origin' })).json();

    const response = await fetch(`/api/projects/${id}/github-candidates/sync`, {
      method: 'POST',
      credentials: 'same-origin',
      headers: {
        'Content-Type': 'application/json',
        [metadata.headerName]: metadata.token,
        'If-Match': String(record.revision),
      },
      body: JSON.stringify({ since: null, idempotencyKey: crypto.randomUUID() }),
    });

    return { status: response.status, body: await response.json() };
  });

  await page.getByTestId('automations-sync-now').click();
  const error = page.getByTestId('automations-sync-error');
  await expect(error).toBeVisible();
  await expect(error).toContainText(direct.body.code);
});

test('Publish and Automations are two steps from anywhere', async ({ page }) => {
  await createProject(page, PROJECT_NAME, 'One project, six addresses.');

  // Step away to the far end of the nav, then come back in two steps:
  // the Projects nav entry, then the card's own deep-link.
  await page.getByTestId('nav-operations').click();
  await expect(page.getByRole('heading', { name: 'Background jobs', exact: true })).toBeVisible();

  await page.getByTestId('nav-projects').click();
  await page
    .getByTestId('dashboard-project')
    .filter({ hasText: PROJECT_NAME })
    .first()
    .locator('xpath=ancestor::li')
    .getByTestId('project-automations-link')
    .click();
  await expect(page.getByTestId('automations-view')).toBeVisible();
  await expect(page.getByTestId('project-area-automations')).toHaveAttribute(
    'aria-current',
    'page',
  );

  // And from an area, every other area is one sub-nav step: no back-link used.
  await page.getByTestId('project-area-publish').click();
  await expect(page.getByTestId('publication-panel')).toBeVisible();
  await expect(page.getByTestId('project-area-publish')).toHaveAttribute('aria-current', 'page');
});

test('DELTA captures: one empty-state screenshot per project area', async ({ page }) => {
  const projectId = await createProject(page, PROJECT_NAME, 'One project, six addresses.');

  for (const area of AREAS) {
    await page.goto(`/projects/${projectId}${area.path}`);
    await expect(page.getByTestId('project-name')).toBeVisible();
    await expect(page.getByTestId(area.testid)).toHaveAttribute('aria-current', 'page');
    await expectSettled(page, area.testid);
    await page.screenshot({ path: `test-results/delta/area-${area.path === '' ? 'overview' : area.path.slice(1)}.png` });
  }
});

/** Waits until the area's own reads have landed, so a DELTA capture shows the rendered state. */
async function expectSettled(page: Page, testid: string) {
  switch (testid) {
    case 'project-area-overview':
      await expect(
        page.getByTestId('milestones-empty').or(page.getByTestId('milestone-list')),
      ).toBeVisible();
      await expect(
        page.getByTestId('timeline-empty').or(page.getByTestId('timeline-entry').first()),
      ).toBeVisible();
      break;
    case 'project-area-evidence':
      await expect(page.getByTestId('github-connection-panel')).toBeVisible();
      await expect(page.getByTestId('github-candidate-panel')).toBeVisible();
      break;
    case 'project-area-content':
      await expect(page.getByTestId('narrative-memory')).toBeVisible();
      // The voice panels are behind a toggle in the design's compact default;
      // the DELTA capture is the area at rest, with the toggle open so the
      // panel it owns is part of the empty-state shape.
      await page.getByTestId('voice-toggle').click();
      await expect(page.getByTestId('voice-profile-panel')).toBeVisible();
      break;
    case 'project-area-publish':
      await expect(page.getByTestId('publication-panel')).toBeVisible();
      await expect(page.getByTestId('journey-panel')).toBeVisible();
      break;
    case 'project-area-evolution':
      await expect(page.getByTestId('evolution-image-panel')).toBeVisible();
      await expect(page.getByTestId('evolution-gif-panel')).toBeVisible();
      break;
    case 'project-area-automations':
      await expect(page.getByTestId('automations-connection-empty')).toBeVisible();
      await expect(page.getByTestId('automations-schedule-empty')).toBeVisible();
      await expect(page.getByTestId('automations-webhook-empty')).toBeVisible();
      await expect(page.getByTestId('automations-jobs-empty')).toBeVisible();
      break;
    default:
      break;
  }
}

async function signIn(page: Page) {
  await page.getByTestId('session-token-input').focus();
  await page.keyboard.type(ACCESS_TOKEN as string);
  await page.keyboard.press('Enter');
  await expect(page.getByRole('heading', { name: 'Owner session' })).toBeVisible();
}

/** Creates a project by clicking, and leaves the page on that project. */
async function createProject(page: Page, name: string, description: string): Promise<string> {
  await page.goto('/projects/new');
  await page.getByTestId('project-name-input').fill(name);
  await page.getByTestId('project-description-input').fill(description);
  await page.getByTestId('project-save').click();

  await expect(page).toHaveURL(/\/projects\/[0-9a-f-]{36}$/);

  return projectIdFrom(page.url());
}

/** Records one confirmed milestone by clicking, and leaves the page on the project. */
async function recordMilestone(page: Page, title: string) {
  await page.getByTestId('milestone-new').click();
  await page.getByTestId('milestone-title-input').fill(title);
  await page.getByTestId('milestone-type-input').selectOption('feature');
  await page.getByTestId('milestone-occurred-at-input').fill('2026-09-28T09:30');
  await page.getByTestId('milestone-save').click();

  await expect(page).toHaveURL(/\/projects\/[0-9a-f-]{36}$/);
}

function projectIdFrom(url: string): string {
  return new URL(url).pathname.split('/').filter((segment) => segment.length > 0)[1] ?? '';
}

async function readRoute(page: Page, path: string) {
  return page.evaluate(async (route) => {
    const response = await fetch(route, { credentials: 'same-origin' });

    return { status: response.status, body: await response.json() };
  }, path);
}
